window.CONTENT_PARTS = window.CONTENT_PARTS || [];
window.CONTENT_PARTS.push({ lang: "en", units: [

{ id: "en-climax", group: "Word banks", order: 89, cat: "phrases", title: "Climax and suspense phrases",
  intro: "The climax is the most exciting part of your story. These phrases are arranged in the order you build a climax: a hint that something is wrong, the big moment, slowing time down, how your body reacts, deciding what to do, the turning point and the relief afterwards. Borrow a few lines, not all of them!",
  blocks: [
    { type: "text", title: "How to use this bank", html: "A good climax does not need danger. A spilled drink on stage, a lost wallet at the MRT station or the last penalty in a match can feel just as tense. Pick <b>one or two</b> lines from each stage below and your climax will climb step by step, like a ladder, before it comes back down." },
    { type: "tip", html: "<b>Tip:</b> Keep it believable. A small accident needs a small reaction (<i>my cheeks burned</i>), not a huge one (<i>my heart exploded</i>). Save the strongest lines for the biggest moment." },

    { type: "chips", title: "Stage 1: Hinting that something is wrong", groups: [
      { title: "Small warning signs", words: ["Something did not feel right.", "The ladder gave a tiny wobble.", "The strap of my bag was hanging by a thread.", "The tray was piled a little too high.", "The floor was still wet from the mop.", "The shoelace I had not tied flapped against my shoe.", "The cup was filled right to the brim.", "The clouds were turning a heavy grey.", "The queue was moving far too slowly.", "My watch said 7.25. The bus left at 7.30.", "The zip of my pencil case would not close.", "The kite string was beginning to fray.", "One of the chair legs looked loose.", "The lid was not screwed on properly.", "The battery icon on the tablet was blinking red.", "The path ahead split into three."],
        ex: "The tray was piled a little too high, but I was in a hurry and did not stop to take anything off.",
        note: "Plant the warning early, then let the reader worry about it while your character does not." },
      { title: "A feeling that something is off", words: ["I had a funny feeling in my stomach.", "A tiny voice told me to slow down.", "I could not shake off the feeling that I had forgotten something.", "Something was missing, but I could not tell what.", "Everything was a little too quiet.", "It was going too well.", "I felt a prickle at the back of my neck.", "A small doubt crept into my mind.", "I should have listened to Mum.", "Little did I know what was about to happen.", "If only I had checked one more time.", "That was my first mistake."],
        ex: "Everything was going too well. That should have been my first clue.",
        note: "“Little did I know” is useful, but use it only once in a composition." },
      { title: "Ticking clock (running out of time)", words: ["with only five minutes to spare", "The clock ticked on.", "Time was running out.", "The minute hand crept towards twelve.", "The doors would close any second.", "We had one last chance.", "The last bus of the night", "Only ten seconds remained on the scoreboard.", "The teacher was already collecting the papers.", "The curtain would rise in two minutes.", "Mum was due home in a quarter of an hour.", "The countdown had begun."],
        ex: "The curtain would rise in two minutes, and my violin bow was nowhere to be found." },
      { title: "The calm before the trouble", words: ["It was an ordinary Saturday morning.", "Nothing could spoil this day, or so I thought.", "I hummed as I carried the tray.", "Everything was ready.", "I had practised the routine a hundred times.", "We were winning easily.", "I felt like the luckiest person in the world.", "I was too busy chatting to look where I was going.", "The hall was buzzing with excitement.", "I skipped down the corridor, swinging my bag.", "The afternoon was bright and peaceful.", "I did not have a care in the world."],
        ex: "I hummed as I carried the tray, too busy chatting to look where I was going.",
        note: "A cheerful, calm start makes the trouble feel bigger when it comes." }
    ] },

    { type: "chips", title: "Stage 2: The moment it happens", groups: [
      { title: "Slips, spills and trips", words: ["My foot slid out from under me.", "I lost my balance.", "My elbow caught the edge of the cup.", "Orange juice spread across the tablecloth.", "The tray tilted. The bowls slid.", "I skidded on the wet floor.", "My shoe caught on the edge of the step.", "I stumbled forward, arms flailing.", "The paint pot tipped over.", "Soup splashed down the front of my uniform.", "The ice cream slid off the cone with a plop.", "I landed in a heap on the grass.", "The bicycle wobbled, swerved and toppled over.", "My water bottle rolled under the stage."],
        ex: "My elbow caught the edge of the cup, and orange juice spread across Ah Ma’s white tablecloth." },
      { title: "Breaking or dropping something", words: ["It slipped through my fingers.", "There was a sharp crack.", "The vase rocked once, twice, then fell.", "The model crashed to the floor.", "Pieces scattered across the tiles.", "A long crack ran down the screen.", "The plate shattered into a dozen pieces.", "The handle came off in my hand.", "The tower of blocks swayed and collapsed.", "My project folder burst open.", "The string snapped.", "The button popped off and rolled away.", "The cake slid sideways off the plate.", "The trophy toppled off the shelf."],
        ex: "The vase rocked once, twice, then fell. For a moment, nobody in the living room moved." },
      { title: "Losing something", words: ["My pocket was empty.", "The wallet was gone.", "I patted every pocket. Nothing.", "My ez-link card was not in my bag.", "I turned my bag upside down.", "The house keys were nowhere to be seen.", "I searched under every desk.", "My heart sank as I unzipped the empty pouch.", "I retraced my steps.", "It had been in my hand a minute ago.", "The worksheet had vanished.", "Someone else’s bag looked exactly like mine.", "My name tag had fallen off somewhere.", "The ticket must have dropped out at the bus stop."],
        ex: "I patted every pocket. Nothing. My ez-link card had been in my hand a minute ago." },
      { title: "Getting lost or separated", words: ["I turned around. Mum was gone.", "None of the faces were familiar.", "Every aisle looked the same.", "I had taken a wrong turn.", "The crowd swallowed my brother.", "I could no longer see Dad’s blue cap.", "The signs pointed in every direction.", "I was walking in circles.", "The path I came on had disappeared.", "I stood alone in the middle of the mall.", "I did not recognise this exit.", "Strangers hurried past without looking at me.", "The group had moved on without me.", "My phone had no battery."],
        ex: "I turned around. Mum was gone. Every aisle in the supermarket looked exactly the same." },
      { title: "Near misses", words: ["just in the nick of time", "by a hair’s breadth", "It missed me by inches.", "I grabbed it just before it hit the ground.", "A bicycle whizzed past, inches away.", "Dad pulled me back by the collar.", "I jumped aside just in time.", "The ball flew past my ear.", "The door swung shut a second after I slipped through.", "I caught the glass with my fingertips.", "The lift doors closed on my bag strap, then sprang open again.", "That was too close.", "One more step and I would have fallen in.", "The cup wobbled on the edge but stayed put."],
        ex: "I lunged and caught the glass with my fingertips, just in the nick of time." },
      { title: "Big performance moments", words: ["The spotlight found me.", "Hundreds of faces stared up at the stage.", "My mind went completely blank.", "The first note came out as a squeak.", "I forgot my next line.", "The music started without me.", "My fingers froze on the keys.", "The microphone gave a loud screech.", "My costume ripped at the seam.", "I stepped onto the stage.", "The hall fell silent.", "My partner missed her cue.", "The backing track stopped halfway.", "It was my turn."],
        ex: "The music started. The spotlight found me. And my mind went completely blank.",
        note: "Concerts, recitals, speech day, show-and-tell and CCA performances are perfect climaxes." },
      { title: "Big match moments", words: ["The score was tied.", "It was the final penalty.", "The whistle was about to blow.", "The ball rolled towards the goal line.", "Only one runner stood between me and the finishing line.", "The baton slipped in my sweaty palm.", "The shuttlecock floated towards the net.", "The ball hit the rim, rolled around and wobbled.", "Our team needed one more point.", "The crowd rose to its feet.", "I had one shot left.", "The goalkeeper dived the wrong way.", "Our captain was carried off with a twisted ankle.", "Everything depended on me now."],
        ex: "The ball hit the rim, rolled around once and wobbled. The whole gym held its breath." },
      { title: "Things that get stuck or stop working", words: ["The lift jerked to a stop.", "The zip was stuck.", "The door would not budge.", "The key would not turn.", "The screen went black.", "The printer jammed.", "My kite was tangled in the tree.", "The lights flickered and went out.", "The cap was jammed on tight.", "My ring was stuck on my finger.", "The ball was wedged between two branches.", "The lock clicked shut with the key inside."],
        ex: "The lift jerked to a stop between the fifth and sixth floors, and the light above the buttons blinked." },
      { title: "Waiting for results", words: ["The judge unfolded the paper.", "The teacher picked up the stack of scripts.", "The results were pinned on the noticeboard.", "The principal leaned towards the microphone.", "“And the winner is ...”", "The envelope was in my hands.", "My name was not called for third place.", "Or second.", "Teacher paused at my desk.", "The scores flashed up on the screen.", "The coach read out the team list slowly.", "There was one name left."],
        ex: "The principal leaned towards the microphone. “And the winner is ...” She paused. I squeezed Priya’s hand." }
    ] },

    { type: "chips", title: "Stage 3: Slowing time down", groups: [
      { title: "Stretching the seconds", words: ["Time seemed to slow down.", "Everything happened in slow motion.", "The seconds stretched like chewing gum.", "It felt like a whole minute, but it was only a second.", "For a moment, the world stood still.", "Each second felt like an hour.", "The clock seemed to stop ticking.", "Time froze.", "It seemed to take forever.", "I watched it happen, unable to move.", "Every step felt like a mile.", "The wait was endless."],
        ex: "For a moment, the world stood still. The plate hung in the air, then began to fall.",
        note: "Slow-motion lines belong at the very peak of the climax, not at the start." },
      { title: "Freeze-frame details (what you notice in that second)", words: ["I could see every crumb on the floor.", "A single drop of juice hung from the edge of the table.", "The ball spun slowly through the air.", "I noticed the tiny chip on the rim of the bowl.", "Dust floated in the beam of the spotlight.", "My reflection stared back at me from the glass door.", "The teacher’s pen paused above the paper.", "A paper cup rolled across the court.", "The coin wobbled on its edge.", "Every head in the canteen turned.", "The bow trembled on the string.", "My shadow stretched across the stage."],
        ex: "The coin wobbled on its edge, round and round, while all of us leaned closer." },
      { title: "Short sentence runs (one beat at a time)", words: ["I stopped. I listened.", "One step. Two steps. Three.", "It tipped. It slid. It fell.", "Closer. Closer.", "Five metres. Three. One.", "I reached. I missed.", "Silence. Then a click.", "Not here. Not there. Nowhere.", "Breathe in. Breathe out.", "Ten seconds. Nine. Eight.", "Left. Right. Left again.", "Almost. Almost."],
        ex: "Five metres. Three. One. I stretched out my hand and slapped the wall.",
        note: "Short sentences make the reader read faster. Use them for two or three lines, then go back to normal sentences." }
    ] },

    { type: "chips", title: "Stage 4: Sounds and silence", groups: [
      { title: "Sudden sounds", words: ["Crash!", "Thud!", "Splash!", "Snap!", "Pop!", "Clang!", "Rrrip!", "a loud bang", "a sharp crack", "a high-pitched screech", "a dull thump", "the clatter of a falling tray", "the shrill ring of the school bell", "the blast of the referee’s whistle", "the squeal of brakes", "a startled gasp from the audience"],
        ex: "Clang! The metal tray hit the canteen floor, and every head turned towards me." },
      { title: "Crowd sounds", words: ["a gasp went up", "a murmur rippled through the hall", "the crowd groaned", "someone giggled", "a few people clapped", "the cheering grew louder and louder", "whispers spread from row to row", "the audience roared", "my teammates shouted my name", "a groan of disappointment", "a burst of applause", "the stands erupted"],
        ex: "A murmur rippled through the hall as I bent to pick up my fallen music sheets." },
      { title: "Small sounds in the quiet", words: ["the tick of the clock", "the hum of the fan", "the drip of a tap", "my own breathing", "the scrape of a chair", "the rustle of paper", "the creak of the door", "the squeak of my shoes", "a faint click", "footsteps in the corridor", "the buzz of the fluorescent light", "someone’s cough at the back of the hall", "the jingle of keys", "the beep of the lift"],
        ex: "The only sound in the hall was the tick of the clock above the stage.",
        note: "A tiny sound in a quiet room builds more tension than a loud one." },
      { title: "Silence lines", words: ["The room fell silent.", "Nobody said a word.", "You could have heard a pin drop.", "The chatter stopped at once.", "A hush fell over the crowd.", "The whole class held its breath.", "Even the birds seemed to stop singing.", "The silence was heavy.", "No one dared to move.", "The music faded away.", "The cheering died down.", "All I could hear was my heartbeat."],
        ex: "The chatter stopped at once. Thirty pairs of eyes stared at the broken jar." }
    ] },

    { type: "chips", title: "Stage 5: Body reactions under pressure", groups: [
      { title: "Heart and breathing", words: ["My heart thumped.", "My heart pounded in my chest.", "My heart skipped a beat.", "My heart was in my mouth.", "I held my breath.", "I gulped.", "My breath came in short gasps.", "I let out a shaky breath.", "My chest felt tight.", "I forgot to breathe.", "I sucked in a sharp breath.", "My heartbeat drummed in my ears."],
        ex: "I held my breath as the judge picked up the microphone." },
      { title: "Hands, legs and feet", words: ["My hands trembled.", "My palms were sweaty.", "My fingers fumbled with the zip.", "My knees went weak.", "My legs felt like jelly.", "My feet seemed glued to the floor.", "I clenched my fists.", "I gripped the railing tightly.", "My fingers turned cold.", "My legs refused to move.", "I bit my nails.", "I hugged my bag to my chest."],
        ex: "My fingers fumbled with the zip of my bag, and the notes inside crumpled." },
      { title: "Face, throat and tummy", words: ["My face went pale.", "My cheeks burned.", "My mouth went dry.", "A lump rose in my throat.", "My stomach churned.", "My tummy did a somersault.", "Sweat trickled down my forehead.", "My eyes stung.", "I bit my lip.", "My ears turned red.", "I swallowed hard.", "A cold shiver ran down my spine."],
        ex: "My mouth went dry. I swallowed hard and stepped up to the microphone.",
        note: "Pick ONE body reaction per sentence. Three in a row sounds like a list." },
      { title: "Eyes and looking", words: ["I stared in disbelief.", "My eyes widened.", "I squeezed my eyes shut.", "I could not tear my eyes away.", "I peeked through my fingers.", "I scanned the crowd.", "My eyes darted left and right.", "I did not dare to look.", "I blinked hard.", "I glanced at the clock again.", "I fixed my eyes on the finishing line.", "I looked up slowly."],
        ex: "I squeezed my eyes shut and waited for the crash. It never came." }
    ] },

    { type: "chips", title: "Stage 6: Thoughts racing", groups: [
      { title: "A busy, panicky mind", words: ["My mind raced.", "Thoughts tumbled over one another.", "A hundred thoughts rushed through my head.", "I could not think straight.", "My brain was a jumble.", "Questions whirled in my mind.", "I tried to remember what Dad had taught me.", "My thoughts went round and round.", "Think, think!", "What now?", "This could not be happening.", "Not now, not today!"],
        ex: "My mind raced. Where had I put the keys? The sofa? The shoe cabinet? The car?" },
      { title: "What-if questions", words: ["What if Mum found out?", "What if I let the team down?", "What if everyone laughed?", "What if it was broken for good?", "What if I never found my way back?", "What if the bus had already left?", "What if I dropped the baton again?", "What if I forgot the words?", "What if nobody came?", "What if Teacher thought I had cheated?"],
        ex: "What if I dropped the baton again? What if I let the whole team down?",
        note: "Two what-if questions are enough. A whole paragraph of them slows the action down." }
    ] },

    { type: "chips", title: "Stage 7: Deciding to act", groups: [
      { title: "Making up my mind", words: ["I had to do something.", "There was no time to lose.", "I took a deep breath.", "It was now or never.", "I made up my mind.", "Without another thought, I ...", "I gathered all my courage.", "I knew what I had to do.", "I could not just stand there.", "Before I could change my mind, I ...", "Gritting my teeth, I ...", "Summoning every ounce of courage, I ...", "I squared my shoulders.", "Here goes, I thought."],
        ex: "I could not just stand there. I took a deep breath and raised my hand." },
      { title: "Moving fast", words: ["I dashed", "I lunged", "I dived", "I sprang forward", "I darted", "I scrambled", "I raced", "I grabbed", "I snatched", "I flung out my arm", "I sprinted", "I leapt", "I hurried", "I spun around", "I pushed through the crowd"],
        ex: "I lunged across the table and snatched the jug before it toppled over." },
      { title: "Getting help (a smart, safe choice)", words: ["I ran to find a teacher.", "I called out for help.", "I pressed the alarm button in the lift.", "I asked a station officer for help.", "I waved to the lifeguard.", "I went to the information counter.", "I borrowed a phone to call Mum.", "I told the bus captain at once.", "I stayed where I was, just like Mum had taught me.", "I shouted for Dad."],
        ex: "I stayed where I was, just like Mum had taught me, and asked the lady at the information counter for help.",
        note: "Examiners and teachers love a character who makes a sensible choice." }
    ] },

    { type: "chips", title: "Stage 8: The turning point", groups: [
      { title: "It works out!", words: ["Just in time!", "I caught it!", "Got it!", "It held.", "The ball sailed into the net.", "The jug landed safely in my hands.", "The note rang out clearly.", "I crossed the finishing line first.", "My fingers closed around the keys.", "The door swung open.", "The wobbling tower stayed standing.", "My voice came back.", "The words came flooding back.", "We had done it!"],
        ex: "My fingers closed around the keys. Got it!" },
      { title: "Help arrives", words: ["A familiar voice called my name.", "A hand grabbed my arm.", "Someone came running.", "Out of the crowd stepped Dad.", "A kind auntie pointed the way.", "The teacher appeared at the door.", "Aisha passed me the spare bow.", "My friend whispered the next line.", "A security guard came over.", "My brother tossed me the ball."],
        ex: "Then a familiar voice called my name. I spun around, and there was Mum, holding two bubble teas." },
      { title: "An unexpected twist", words: ["To my surprise,", "To my amazement,", "But that was not the end.", "It was not what I expected at all.", "It turned out that ...", "The wallet had been in my school bag all along.", "It was only my brother hiding behind the curtain.", "The mystery noise was the neighbour’s cat.", "Nobody had noticed my mistake.", "The audience thought it was part of the show!", "Instead of scolding me, Dad burst out laughing.", "The broken piece fitted back perfectly."],
        ex: "To my amazement, the audience clapped. They thought my slip was part of the dance!" },
      { title: "Trying again", words: ["I picked myself up.", "I tried once more.", "This time, I went slowly.", "I took a step back and thought.", "I started the song again from the chorus.", "I dusted off my knees and kept running.", "I steadied my hands.", "Second time lucky!", "I would not give up now.", "I gave it one last push.", "With a final tug, it came loose.", "I counted to three and tried again."],
        ex: "I dusted off my knees and kept running. The finishing line was still there, and so was I." }
    ] },

    { type: "chips", title: "Stage 9: The release of tension", groups: [
      { title: "Body relaxing", words: ["I breathed a sigh of relief.", "I let out the breath I had been holding.", "My shoulders dropped.", "My legs went wobbly.", "I sank onto the bench.", "The knot in my stomach untied itself.", "My heartbeat slowed down.", "I slumped against the wall.", "My hands finally stopped shaking.", "A huge weight lifted off my shoulders.", "I wiped my sweaty palms on my shorts.", "I flopped onto the grass."],
        ex: "I let out the breath I had been holding and sank onto the bench." },
      { title: "Relief and laughter", words: ["Phew!", "That was close!", "We both burst out laughing.", "I laughed shakily.", "Tears of relief filled my eyes.", "Mum hugged me tightly.", "I grinned from ear to ear.", "Everyone cheered.", "My teammates lifted me up.", "We giggled until our tummies hurt.", "Dad ruffled my hair.", "I could not stop smiling."],
        ex: "Mum hugged me so tightly that I could hardly breathe, and then we both burst out laughing." },
      { title: "What people said afterwards", words: ["“Are you okay?”", "“You gave us such a fright!”", "“That was amazing!”", "“Don’t worry, it happens to everyone.”", "“I’m just glad you’re safe.”", "“Well done for staying calm.”", "“Next time, tell me first, okay?”", "“We did it!”", "“I knew you could do it.”", "“It’s only a cup. You’re more important.”", "“Where have you been?”", "“Let’s get you home.”"],
        ex: "Dad knelt down beside me. “It’s only a cup,” he said gently. “You’re more important.”" },
      { title: "Looking back calmly", words: ["Looking back, it was not so bad after all.", "I would never forget that afternoon.", "It was a lesson I learned the hard way.", "From then on, I always double-checked.", "I had been more afraid than I needed to be.", "It all happened in less than a minute.", "I promised myself to be more careful.", "Now I can laugh about it.", "That day, I learned to stay calm.", "It was the longest minute of my life."],
        ex: "It all happened in less than a minute, but it was the longest minute of my life." }
    ] },

    { type: "chips", title: "Cliffhanger lines (to end a paragraph)", groups: [
      { title: "Lines that make the reader turn the page", words: ["That was when I heard it.", "And then everything went wrong.", "But I had spoken too soon.", "I had no idea what was coming next.", "I opened the box and froze.", "Then the lights went out.", "That was the moment the music stopped.", "I looked down. My bag was open.", "Someone had taken my seat.", "The door clicked shut behind me.", "The bus pulled away without me.", "Then the teacher called my name.", "I reached into my pocket. It was empty.", "There was only one problem.", "It was not mine.", "And that was when I saw the crack.", "Just one more step, I told myself.", "Nothing could go wrong now. Or so I thought."],
        ex: "I smiled and took a bow. Nothing could go wrong now. Or so I thought.",
        note: "End a paragraph on the cliffhanger, then start the next paragraph with the action." },
      { title: "Questions to end a paragraph", words: ["What was I going to do now?", "How would I ever explain this?", "Would I make it in time?", "Who could have done this?", "Where could it have gone?", "Was it too late?", "Had anyone seen me?", "Would the glue hold?", "What was inside the box?", "Could I really do it?"],
        ex: "The bus doors hissed shut. I was on the wrong side of them. What was I going to do now?" }
    ] },

    { type: "chips", title: "Suspense connectors", groups: [
      { title: "Sudden events", words: ["Just then,", "Without warning,", "Suddenly,", "All of a sudden,", "Out of nowhere,", "In a flash,", "Before I knew it,", "In the blink of an eye,", "At that very moment,", "Out of the blue,", "Then, without a sound,", "Quick as lightning,"],
        ex: "Without warning, the fan above us gave a loud rattle and stopped.",
        note: "Do not start every sentence with “Suddenly”. Swap between these." },
      { title: "Building up slowly", words: ["Slowly,", "Little by little,", "Inch by inch,", "Step by step,", "Bit by bit,", "As the seconds ticked by,", "The longer I waited,", "Moments later,", "After what felt like forever,", "Gradually,", "One by one,", "Second by second,"],
        ex: "Inch by inch, I stretched my arm towards the ball under the stage." },
      { title: "Turning the story", words: ["Just as I was about to give up,", "Just when I thought it was over,", "No sooner had I ... than ...", "Before I could react,", "Hardly had I sat down when ...", "At the last second,", "At long last,", "Only then did I realise", "To my horror,", "To my relief,", "Seconds later,", "Finally,"],
        ex: "Just as I was about to give up, I spotted a flash of blue under the bench.",
        note: "“No sooner had ... than” and “Hardly had ... when” are for upper primary (P5–P6)." }
    ] },

    { type: "table", title: "Flat climax or tense climax?", head: ["Flat", "Tense"], weakCol: 0, rows: [
      ["I dropped the cake.", "The plate tilted. The cake began to slide. I lunged, but it was too late. Splat!"],
      ["I was nervous on stage.", "The spotlight found me. My mouth went dry, and I gripped the microphone with both hands."],
      ["I lost my wallet.", "I patted every pocket. Nothing. My heart sank."],
      ["We won the match.", "The ball hit the rim, wobbled and dropped through the net. The crowd rose to its feet."],
      ["I found my mum.", "Then a familiar voice called my name. I spun around and ran straight into Mum’s arms."]
    ] },

    { type: "mcq", title: "Quick check", intro: "Choose the best line for each stage of the climax.", items: [
      { q: "Which line HINTS that something will go wrong?", o: ["We cheered loudly.", "The ladder gave a tiny wobble.", "Phew, that was close!"], a: 1, e: "A small wobble is a warning sign. The reader starts to worry." },
      { q: "Which line SLOWS time down?", o: ["The plate hung in the air for a moment.", "Then we went home.", "After that, I ate my lunch."], a: 0, e: "Freezing on one detail makes the moment feel longer." },
      { q: "Which body reaction suits a small mistake, like spilling juice?", o: ["My heart exploded.", "I fainted on the spot.", "My cheeks burned."], a: 2, e: "Burning cheeks are believable for a small, embarrassing accident." },
      { q: "Which is a good cliffhanger to end a paragraph?", o: ["I reached into my pocket. It was empty.", "I went to bed and slept well.", "We had a nice day."], a: 0, e: "An empty pocket makes the reader ask “What now?” and read on." },
      { q: "Which connector shows something happening very suddenly?", o: ["Little by little,", "Without warning,", "Step by step,"], a: 1, e: "“Without warning” jumps the action forward. The others build slowly." },
      { q: "Which line shows the RELEASE of tension?", o: ["My mind raced.", "Time was running out.", "My shoulders dropped, and I let out a long breath."], a: 2, e: "Shoulders dropping and breathing out show the character relaxing." },
      { q: "Which is the most sensible choice when you are lost in a mall?", o: ["I asked the lady at the information counter for help.", "I left the mall to look outside.", "I followed a stranger home."], a: 0, e: "Asking staff for help is safe and shows good thinking." }
    ] }
  ] },

{ id: "en-thoughts", group: "Word banks", order: 90, cat: "people", title: "Thoughts and inner voice",
  intro: "Readers love to hear what your character is thinking. Use these lines to show worry, hope, guilt, decisions and sudden realisations, so your reader feels as if they are inside your head.",
  blocks: [
    { type: "text", title: "Two ways to write a thought", html: "<b>1. With a thinking verb:</b> I wondered if Mum would be angry.<br><b>2. As the actual words in your head</b>, usually in italics when typed (or underlined when handwritten): <i>Mum is going to be so angry,</i> I thought.<br><br>Thoughts in your head do not need speech marks. Keep them short, like real thoughts." },
    { type: "tip", html: "<b>Tip:</b> Use one or two inner-voice lines at the important moments of your story, such as the problem, the decision and the ending. Too many and your story stops moving." },

    { type: "chips", title: "Ways to introduce a thought", groups: [
      { title: "Thinking verbs", words: ["I thought", "I wondered", "I told myself", "I reminded myself", "I asked myself", "I realised", "I remembered", "I worried", "I hoped", "I wished", "I imagined", "I pictured", "I guessed", "I decided", "I recalled", "I muttered to myself", "I whispered to myself", "I kept thinking"],
        ex: "<i>Just one more lap,</i> I told myself, even though my legs were aching.",
        note: "“I told myself” and “I reminded myself” are great for brave or calming thoughts." },
      { title: "The voice in my head", words: ["a small voice in my head", "a little voice inside me", "a nagging voice", "the voice of my conscience", "a sensible voice in my head", "a stubborn part of me", "a tiny voice at the back of my mind", "Mum’s words echoed in my head", "Teacher’s advice rang in my ears", "one part of me ... but another part ...", "my heart said ... but my head said ...", "deep down, I knew"],
        ex: "A small voice in my head whispered, <i>Tell the truth.</i>" },
      { title: "A thought pops in", words: ["A thought flashed through my mind.", "An idea struck me.", "It suddenly occurred to me that", "It dawned on me that", "A question popped into my head.", "The thought crossed my mind that", "I could not stop thinking about", "The idea would not go away.", "A memory came flooding back.", "My mind drifted back to", "In a flash, I knew", "All at once, I understood"],
        ex: "An idea struck me. If I stood on the bench, I could reach the shuttlecock." },
      { title: "Stronger thinking words (upper primary)", words: ["I pondered", "I puzzled over", "I argued with myself", "I debated whether to", "I convinced myself", "I tried to persuade myself", "I reassured myself", "I could not help wondering", "I comforted myself with the thought that", "I asked myself again and again", "I turned the problem over in my mind", "I braced myself"],
        ex: "I turned the problem over in my mind all through recess, but I still did not know what to say to Aisha.",
        note: "These are for P5–P6. Younger writers can stick to “I thought” and “I wondered”." },
      { title: "Lines to put after a thought", words: [", I thought.", ", I told myself firmly.", ", I thought to myself.", ", I wondered.", ", I said under my breath.", ", I muttered.", ", I hoped silently.", ", I reminded myself.", ", I prayed.", ", I scolded myself."],
        ex: "<i>Why did I say that?</i> I scolded myself all the way home.",
        note: "If the thought is a question, put the question mark inside the thought and use a small letter after it." }
    ] },

    { type: "chips", title: "Worry and hope", groups: [
      { title: "Worry thoughts", words: ["Oh no.", "This is bad.", "I am in so much trouble.", "Mum is going to be so upset.", "Everyone is staring at me.", "What will Teacher say?", "Please don’t let it be broken.", "I am never going to finish in time.", "They are going to laugh at me.", "I should never have touched it.", "What if I am late again?", "I can’t do this.", "Where could it be?", "It was right here a minute ago!", "Please, please be in my bag."],
        ex: "<i>It was right here a minute ago!</i> I thought, digging through my bag for the third time." },
      { title: "Nervous before a big event", words: ["What if I trip on the stairs?", "My name is next.", "Don’t look at the audience.", "Just remember the first line.", "Everyone else looks so ready.", "I hope my voice doesn’t crack.", "Why did I volunteer?", "I can still hear my heart.", "Only two more people before me.", "Did I bring my water bottle?", "It will be over in five minutes.", "Just get through the first bit."],
        ex: "<i>Only two more people before me,</i> I thought, smoothing my skirt for the tenth time." },
      { title: "Hope thoughts", words: ["Please let it be good news.", "Maybe it isn’t so bad.", "Just this once, let me win.", "Maybe nobody noticed.", "If I practise every day, I might make the team.", "Maybe she will forgive me.", "Perhaps the shop is still open.", "Please be there, please be there.", "Maybe tomorrow will be better.", "If only it would stop raining.", "I hope Grandpa likes it.", "Let my name be on the list.", "One more point. Just one more."],
        ex: "<i>Let my name be on the list,</i> I hoped silently as I squeezed to the front of the noticeboard." },
      { title: "Wishing", words: ["I wish I could fly away.", "I wish Grandma could see this.", "If only I were taller.", "I wish I had a brother to play with.", "I wish we could stay here forever.", "If only the holidays were longer.", "I wish I could be as brave as Dad.", "I wish I could start again.", "I wish she would talk to me.", "If only I had one more chance."],
        ex: "<i>I wish Grandma could see this,</i> I thought, looking at the ribbon pinned to my shirt." }
    ] },

    { type: "chips", title: "Guilt and regret", groups: [
      { title: "Guilt thoughts", words: ["It was my fault.", "I should own up.", "She is taking the blame for me.", "That wasn’t fair of me.", "I have to tell the truth.", "How could I have been so selfish?", "He looked so hurt.", "I never meant to upset her.", "My friend trusted me.", "I can’t pretend it didn’t happen.", "Someone else is going to get scolded.", "I knew it was wrong, but I did it anyway.", "Mum would be so disappointed in me."],
        ex: "Wei Ming stood with his head down while Teacher scolded him. <i>She is taking the blame for me,</i> I thought, and my cheeks burned.",
        note: "Guilt thoughts are the turning point of honesty compositions." },
      { title: "Hearing the truth in my head", words: ["Be honest.", "Do the right thing.", "You know it’s wrong.", "Put it back.", "It’s not yours to keep.", "Cheating isn’t winning.", "A real friend would speak up.", "Don’t follow the crowd.", "What would Grandpa say?", "Lying will only make it worse.", "Say sorry. Mean it.", "You’ll feel better once it’s done."],
        ex: "The ten-dollar note lay on the floor of the MRT train. <i>It’s not yours to keep,</i> said the small voice in my head." },
      { title: "Relieved thoughts", words: ["Thank goodness.", "It’s over.", "That wasn’t so bad.", "She isn’t angry after all.", "I’m so glad I told the truth.", "I can finally breathe.", "Everything is going to be okay.", "Why was I so worried?"],
        ex: "<i>She isn’t angry after all,</i> I thought, as Mum pulled me into a hug." },
      { title: "Regret thoughts", words: ["If only I had listened.", "I wish I could take it back.", "Why didn’t I check?", "I should have said sorry earlier.", "If only I had left five minutes earlier.", "Why did I laugh at her?", "I should have practised more.", "I wish I had been kinder.", "What was I thinking?", "If I could turn back time, I would ...", "I should have asked for help.", "Why didn’t I just tell the truth?"],
        ex: "<i>If only I had listened to Dad,</i> I thought, staring at the flat tyre." },
      { title: "Getting ready to own up", words: ["What do I even say?", "Just say it. Say sorry.", "Start with the truth.", "She might be angry, but she deserves to know.", "It will only get worse if I wait.", "I’ll explain everything.", "Don’t make excuses.", "Look her in the eye.", "It’s better to hear it from me.", "I’ll offer to pay for it with my savings.", "Ten seconds of courage. That’s all.", "Whatever she says, I’ll accept it."],
        ex: "<i>Ten seconds of courage. That’s all,</i> I told myself, and I walked up to Mrs Tan’s desk." }
    ] },

    { type: "chips", title: "Making a decision", groups: [
      { title: "Weighing it up", words: ["Should I tell Teacher, or keep quiet?", "Should I go back, or carry on?", "If I tell, they might be angry. If I don’t, I’ll feel terrible.", "On the one hand ... on the other hand ...", "It would be so easy to walk away.", "Nobody would ever know.", "But I would know.", "Which was more important, winning or being fair?", "Part of me wanted to run. Part of me wanted to stay.", "Was it worth it?", "What would Mum do?", "What would a good friend do?"],
        ex: "<i>Nobody would ever know,</i> I thought. Then another thought followed. <i>But I would know.</i>",
        note: "Show both sides first. It makes the final choice much stronger." },
      { title: "The decision is made", words: ["That settled it.", "I knew what I had to do.", "I am going to tell the truth.", "Right. No more excuses.", "I will say sorry first.", "That’s it. I’m going back.", "Enough is enough.", "My mind was made up.", "I am not giving up now.", "I will share it with her.", "I’ll do it right now, before I lose my nerve.", "Whatever happens, I’ll be honest."],
        ex: "<i>I’ll do it right now, before I lose my nerve,</i> I told myself, and I knocked on the staffroom door." },
      { title: "Changing my mind", words: ["On second thoughts ...", "Then again, maybe not.", "No, that’s not right.", "Wait. That’s not fair to her.", "Maybe I was wrong.", "I had a better idea.", "Actually, I could try another way.", "Perhaps it wasn’t worth arguing about.", "Hold on. What if she’s right?", "I turned back."],
        ex: "I was about to grab the last curry puff. <i>Wait. That’s not fair to her,</i> I thought, and I pushed the plate towards my sister." }
    ] },

    { type: "chips", title: "Being brave and calm", groups: [
      { title: "Self-encouragement", words: ["You can do this.", "Come on, keep going.", "Just one more step.", "Don’t give up now.", "You’ve practised this a hundred times.", "Focus.", "Eyes on the ball.", "Remember your training.", "Almost there.", "It’s just like at home.", "Be brave.", "You’ve got this.", "Finish what you started.", "Show them what you can do."],
        ex: "<i>You’ve practised this a hundred times,</i> I told myself as I lifted the flute to my lips." },
      { title: "Keeping going when I’m tired", words: ["Only one more lap.", "Don’t stop now.", "Think of the finishing line.", "Your legs can rest later.", "Just reach the next lamp post.", "Everyone is tired, not just you.", "Keep your arms pumping.", "Remember why you started.", "Ten more steps.", "Push, push, push!", "The team is counting on you.", "You’re nearly there."],
        ex: "<i>Just reach the next lamp post,</i> I told myself. Then the next one. Then the next." },
      { title: "Calming myself down", words: ["Stay calm.", "Breathe.", "Count to five.", "Don’t panic.", "It’s okay to make a mistake.", "One thing at a time.", "Slow down and think.", "It’s not the end of the world.", "Mum will understand.", "Just think about the next step.", "Nobody is perfect.", "Relax your shoulders."],
        ex: "<i>Don’t panic. One thing at a time,</i> I reminded myself, and I read the question again slowly." }
    ] },

    { type: "chips", title: "Realising and understanding", groups: [
      { title: "Sudden realisations", words: ["Of course!", "That’s it!", "Wait a minute.", "Hang on.", "So that’s why!", "How could I have missed it?", "It was in my other pocket all along!", "She wasn’t angry. She was hurt.", "He only wanted to help.", "It was never about the prize.", "I had been wrong about her.", "Now it all makes sense.", "Oh. I’m the one who left it there."],
        ex: "<i>Wait a minute.</i> I looked at the date again. The test was tomorrow, not today!",
        note: "A realisation often comes at the turning point or the ending." },
      { title: "Learning a lesson", words: ["Now I understand what Mum meant.", "Being honest felt better than winning.", "Sharing made it more fun, not less.", "Practice really does make a difference.", "I didn’t have to do it all alone.", "Mistakes are how we learn.", "Kindness costs nothing.", "Next time, I will check first.", "Grandma was right after all.", "Friends matter more than marks."],
        ex: "As I walked home, I smiled. <i>Being honest felt better than winning.</i>" },
      { title: "Noticing clues (detective thoughts)", words: ["That’s strange.", "Those footprints weren’t there before.", "Why is the window open?", "Someone has been here.", "That sound is coming from the cupboard.", "Hmm, the biscuit tin is lighter.", "Only one person had the key.", "The crumbs led under the sofa.", "She was the last one in the classroom.", "That’s not my handwriting.", "Something doesn’t add up.", "I’ve seen that bag somewhere before."],
        ex: "<i>Hmm, the biscuit tin is lighter,</i> I thought, and then I noticed the crumbs leading under the sofa." }
    ] },

    { type: "chips", title: "Wondering and remembering", groups: [
      { title: "Wondering", words: ["I wonder what’s inside.", "Who could have left it here?", "What would happen if I pressed it?", "Where does this path go?", "Why is she sitting alone?", "Was he telling the truth?", "What would it be like to fly?", "How did the cat get up there?", "I wonder if she remembers me.", "What would Grandpa think?", "Is it really for me?", "Could it be ...?"],
        ex: "<i>Why is she sitting alone?</i> I wondered, watching the new girl at the corner table during recess." },
      { title: "Imagining what might happen", words: ["I imagined Mum’s face when she saw it.", "I pictured myself on the stage.", "Maybe one day I’ll be a vet.", "What would I be like in ten years?", "I could already taste the chicken rice.", "I imagined the crowd cheering.", "Maybe we’ll be best friends.", "I pictured Grandpa opening the present.", "What if I really won?", "I could almost feel the medal around my neck."],
        ex: "I pictured Grandpa opening the present, his eyes crinkling in surprise." },
      { title: "Remembering", words: ["I remembered the first time I tried.", "Grandma’s words came back to me.", "I thought of last year’s race.", "It reminded me of the time ...", "A picture of Dad’s smile flashed into my mind.", "I could still hear Coach saying, “Never give up.”", "Just like the time I fell off my bicycle,", "I remembered how kind she had been to me.", "Memories of our holiday came rushing back.", "I thought of all the mornings I had practised.", "I remembered Mum’s warning.", "That smell took me straight back to Ah Ma’s kitchen."],
        ex: "I thought of all the mornings I had practised at the void deck, and my legs felt stronger." },
      { title: "Things that bring back memories", words: ["the smell of pandan cake", "the sound of rain on the zinc roof", "an old song on the radio", "a faded photograph", "Grandpa’s old watch", "the swing at the playground", "the taste of Mum’s soup", "my old school badge", "the creak of the gate", "a birthday card in the drawer"],
        ex: "The smell of pandan cake took me straight back to Ah Ma’s kitchen, and I remembered her laughing as she floured my nose." },
      { title: "Comparing", words: ["Everyone else seemed so confident.", "Her drawing was much better than mine.", "Last year, I would have cried.", "I used to be scared of the water. Not any more.", "Why can’t I be like my brother?", "He made it look so easy.", "Compared to yesterday, this was nothing.", "I was not the fastest, but I was not the slowest either.", "A month ago, I couldn’t even float.", "Maybe I didn’t need to be like anyone else.", "Other people had problems too.", "Everyone starts somewhere."],
        ex: "<i>Last year, I would have cried,</i> I thought. <i>This year, I’m going to finish.</i>" }
    ] },

    { type: "chips", title: "Other feelings in the head", groups: [
      { title: "Surprise thoughts", words: ["Is this real?", "I can’t believe it!", "No way!", "Me? Really?", "Am I dreaming?", "That can’t be right.", "Did she just say my name?", "How did they know?", "This is the best day ever!", "I must be seeing things."],
        ex: "<i>Me? Really?</i> I thought, as the principal read out my name." },
      { title: "Embarrassed thoughts", words: ["I wish the ground would swallow me up.", "Everyone saw that.", "Why do these things always happen to me?", "Please stop looking at me.", "Act normal.", "Pretend nothing happened.", "I’ll never live this down.", "Maybe I can just slip away.", "Of all the days to wear odd socks!", "Just smile and keep going."],
        ex: "<i>Just smile and keep going,</i> I told myself, brushing the sand off my knees." },
      { title: "Annoyed or frustrated thoughts", words: ["Not again!", "Why won’t it work?", "This is so unfair.", "I’ve tried everything!", "Why is he always first?", "Can’t anyone see I’m busy?", "Why does this keep happening?", "I give up. No, wait.", "Stay patient.", "It’s only a game.", "Counting to ten won’t hurt.", "Getting angry won’t fix it."],
        ex: "<i>Why won’t it work?</i> I glared at the robot. Then I remembered Coach’s words. <i>Getting angry won’t fix it.</i>" },
      { title: "Jealous or left-out thoughts", words: ["Why wasn’t I invited?", "They didn’t even ask me.", "Everyone has a partner except me.", "Her bag is so much nicer.", "Why does he get all the attention?", "Nobody would notice if I left.", "Maybe they don’t like me.", "I want to be part of the group.", "Maybe I could ask to join.", "Perhaps they just forgot."],
        ex: "<i>Everyone has a partner except me,</i> I thought, looking down at my shoes. Then Jun Hao waved me over." },
      { title: "Excited, looking-forward thoughts", words: ["Only one more sleep!", "I can’t wait!", "This is going to be amazing.", "I wonder what we’ll see first.", "Tomorrow can’t come fast enough.", "I’m going to try everything.", "Will it be as fun as last year?", "I’ve packed my bag three times already.", "Just one more day of school.", "I hope it doesn’t rain."],
        ex: "<i>Only one more sleep!</i> I thought, staring at the ceiling with my packed bag beside the bed." },
      { title: "Missing someone or feeling sad", words: ["It’s so quiet without her.", "I miss Grandpa’s stories.", "I wish he hadn’t moved away.", "Nobody laughs at my jokes like she did.", "Her chair looks so empty.", "I’ll write her a letter.", "Maybe we can video call tonight.", "It won’t be the same.", "I’ll keep her drawing forever.", "I’m glad I got to know her."],
        ex: "<i>Her chair looks so empty,</i> I thought on the first day of term. <i>I’ll write her a letter tonight.</i>" },
      { title: "Grateful thoughts", words: ["I’m so lucky to have her as a friend.", "Mum never complains.", "He didn’t have to help me, but he did.", "I should say thank you properly.", "I never noticed how much Dad does.", "Without Coach, I would have quit.", "I take so much for granted.", "I’m glad we had this day together.", "Some people don’t have what I have.", "I’ll make Grandma proud."],
        ex: "<i>He didn’t have to help me, but he did,</i> I thought, watching the cleaner uncle sweep up the mess I had made." },
      { title: "Proud and happy thoughts", words: ["I did it!", "All that practice was worth it.", "I really did it all by myself.", "Wait until I tell Mum!", "This is the best feeling in the world.", "I’m glad I didn’t give up.", "Maybe I am braver than I thought.", "I can’t stop smiling.", "That was worth every early morning.", "I want to remember this forever."],
        ex: "<i>All that practice was worth it,</i> I thought, holding the medal tightly." },
      { title: "Thinking about others", words: ["She must feel so lonely.", "He looked like he needed a friend.", "How would I feel if that were me?", "Grandpa must be tired.", "Mum works so hard for us.", "Maybe he was just having a bad day.", "She was only trying to help.", "I should have asked if she was okay.", "Maybe I could cheer him up.", "They must be so worried about me."],
        ex: "<i>How would I feel if that were me?</i> I thought, and I walked over to sit beside him." }
    ] },

    { type: "chips", title: "Questions a character asks themselves", groups: [
      { title: "When something goes wrong", words: ["What have I done?", "How am I going to fix this?", "Who can I ask for help?", "Why did this have to happen today?", "Can it be glued back together?", "How will I explain this?", "Where did I go wrong?", "Is there still time?"],
        ex: "<i>How am I going to fix this?</i> I stared at the torn page, my mind racing." },
      { title: "When I must choose", words: ["Should I say something?", "Is it really my business?", "What is the right thing to do?", "Would I want someone to do that to me?", "Am I brave enough?", "Is it worth getting into trouble?", "What if I’m wrong?", "Which friend should I believe?"],
        ex: "<i>Would I want someone to do that to me?</i> The answer was clear." },
      { title: "When I look back", words: ["Had I done the right thing?", "Why had I been so afraid?", "Would I do it again?", "What had I learned?", "Was winning really that important?", "How could I have been so careless?", "Why did I wait so long to say sorry?", "Would she ever trust me again?"],
        ex: "That night, I lay in bed and asked myself, <i>Had I done the right thing?</i> This time, I knew the answer was yes.",
        note: "A thoughtful question in the last paragraph makes a strong ending." },
      { title: "When I doubt myself", words: ["Am I good enough?", "Why did they choose me?", "What if I let everyone down?", "Can I really do this?", "Do I belong here?", "What if I’m the only one who doesn’t understand?", "Will they still like me if I lose?", "Have I practised enough?"],
        ex: "<i>Why did they choose me?</i> I wondered, holding the captain’s armband." },
      { title: "Last thoughts to end a story", words: ["I would never forget that day.", "I was stronger than I knew.", "Some mistakes are worth making.", "Next time, I will be ready.", "I hope she remembers it too.", "It was the best decision I ever made.", "I had learned something no textbook could teach me.", "I couldn’t wait to try again.", "From now on, I’ll be a better friend.", "Sometimes, the small things matter most."],
        ex: "As the bus pulled away, I looked out of the window and smiled. <i>I was stronger than I knew.</i>" }
    ] },

    { type: "table", title: "Telling or inner voice?", head: ["Telling", "Inner voice"], weakCol: 0, rows: [
      ["I was worried about the test.", "<i>What if I forget everything?</i> I thought, flipping through my notes again."],
      ["I felt guilty.", "<i>She is taking the blame for me,</i> I thought, and I could not look at her."],
      ["I decided to tell the truth.", "<i>Right. No more excuses,</i> I told myself, and I raised my hand."],
      ["I suddenly understood.", "<i>Of course!</i> It had been in my other pocket all along."],
      ["I was proud of myself.", "<i>I really did it all by myself,</i> I thought, grinning at the finished model."]
    ] },

    { type: "mcq", title: "Quick check", intro: "Choose the best inner-voice line for each moment.", items: [
      { q: "Priya is about to sing a solo. Which thought shows SELF-ENCOURAGEMENT?", o: ["<i>Everyone is staring at me.</i>", "<i>You’ve practised this a hundred times.</i>", "<i>I wish I could go home.</i>"], a: 1, e: "Reminding yourself of your practice helps you feel brave." },
      { q: "Jun Hao’s friend is blamed for something Jun Hao did. Which thought shows GUILT?", o: ["<i>She is taking the blame for me.</i>", "<i>What a lucky escape!</i>", "<i>I wonder what’s for lunch.</i>"], a: 0, e: "He knows someone else is suffering for his mistake." },
      { q: "Which line is a REGRET thought?", o: ["<i>I can’t wait for Saturday.</i>", "<i>Let my name be on the list.</i>", "<i>If only I had listened to Dad.</i>"], a: 2, e: "“If only I had ...” looks back and wishes it had gone differently." },
      { q: "Which is correctly punctuated?", o: ["<i>Why did I say that?</i> I scolded myself.", "<i>Why did I say that,</i> I scolded myself?", "“Why did I say that.” I scolded myself."], a: 0, e: "The question mark belongs inside the thought, and thoughts do not need speech marks." },
      { q: "Which thought shows a sudden REALISATION?", o: ["<i>Please be there.</i>", "<i>Wait a minute. The test is tomorrow!</i>", "<i>Come on, keep going.</i>"], a: 1, e: "“Wait a minute” shows the character has just understood something." },
      { q: "Which question would make a thoughtful ENDING?", o: ["<i>Where is my pencil?</i>", "<i>What time is it?</i>", "<i>Had I done the right thing?</i>"], a: 2, e: "It makes the character, and the reader, think back on the whole story." }
    ] }
  ] }

] });
